// EDIT RULES: OFF LIMITS, to people and AIs alike. This file is one of the suite's rules (SUITE-RULES.md). A change to it, a move, a rename or a deletion is a change outside a YOURS block: regenerating will overwrite it, SR-16 reports it and suite verify finds it. To get a test through, fix the test or push back on the story; to change a rule, change Suite Builder.
package com.playwrightplayground.tests;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.parallel.Isolated;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

import java.io.IOException;
import java.nio.file.Paths;
import java.util.List;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The suite checks itself, with every whole run ({@code mvn test}; -Dgroups=rules alone), last, in well under a
 * second and without a browser: one entry per rule in SUITE-RULES.md, so the report says which rule a
 * test broke ("SR-19 Every test checks something"), and the failure says where, why the rule exists,
 * and what to write instead. A hard or story rule broken fails here, and only here: the other tests
 * run whatever it says. An advisory rule broken is a warning, printed and in target/rules-report.md.
 */
@Tag("rules")
@Order(Integer.MAX_VALUE)
@Isolated
class SuiteRulesTest {

    @TestFactory
    @DisplayName("The suite's rules (SUITE-RULES.md)")
    Stream<DynamicTest> theSuitesRules() throws IOException {
        List<String> problems = SuiteRules.report(SuiteRules.check(Paths.get(System.getProperty("user.dir"))));
        return SuiteRules.RULES.stream().map(rule -> DynamicTest.dynamicTest(rule.id() + " " + rule.name() + " (" + rule.tier() + ")", () -> {
            String tag = "[" + rule.id() + "] ";
            List<String> broken = problems.stream().filter(p -> p.startsWith(tag)).map(p -> p.substring(tag.length())).toList();
            StringBuilder message = new StringBuilder(rule.id() + " " + rule.name() + ": broken " + broken.size()
                    + (broken.size() == 1 ? " time" : " times") + ".\n");
            for (int i = 0; i < broken.size(); i++) message.append("  ").append(i + 1).append(". ").append(broken.get(i)).append('\n');
            message.append("Why the rule: ").append(rule.why()).append('\n');
            message.append("How to fix it: ").append(rule.fix()).append('\n');
            message.append("More, with examples: ai/rules-in-full.md, ").append(rule.id()).append('.');
            if (rule.fails()) assertTrue(broken.isEmpty(), message.toString());
        }));
    }

    @Test
    @DisplayName("Every problem the rules find belongs to a rule")
    void everyProblemHasItsRule() throws IOException {
        List<String> problems = SuiteRules.check(Paths.get(System.getProperty("user.dir")));
        List<String> strays = problems.stream()
                .filter(p -> SuiteRules.RULES.stream().noneMatch(r -> p.startsWith("[" + r.id() + "] ")))
                .toList();
        assertTrue(strays.isEmpty(), "Problems no rule claims (a fault in SuiteRules itself: regenerate the suite): " + strays);
    }
}
